package dev.nosferatu.bombaychitra

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.put

enum class MapTheme(val styleName: String) { Light("light"), Dark("dark") }

/**
 * BombayChitra's MapLibre styles, as generated by its web build (`web/src/map/style`), made usable on a phone.
 *
 * The styles are BombayChitra's own and are not restyled here. Only the two URLs that point at a BombayChitra
 * server change: the single vector source `bc` and the glyphs. Everything Nosferatu draws (position, trail,
 * corrections) is added later as separate layers above BombayChitra's, so the map's identity is untouched.
 */
object BombayChitraStyle {
    /** The id of the one vector source in every BombayChitra style. */
    const val SOURCE_ID = "bc"

    const val ATTRIBUTION = "BombayChitra · © OpenStreetMap contributors · © Overture Maps Foundation"

    private val json = Json { prettyPrint = false }

    /**
     * Rewrites a style so it reads tiles from a local PMTiles archive and glyphs bundled with the app.
     *
     * @param template the style JSON exactly as BombayChitra serves it (`/styles/dark.json`).
     * @param pmtilesUri e.g. `pmtiles://file:///data/…/bombaychitra.pmtiles`.
     * @param glyphsUri e.g. `asset://fonts/{fontstack}/{range}.pbf`.
     * @throws UnsupportedStyleException if the style does not have BombayChitra's `bc` vector source.
     */
    fun offline(template: String, pmtilesUri: String, glyphsUri: String): String {
        val style = json.parseToJsonElement(template).jsonObject
        val sources = style["sources"] as? JsonObject
            ?: throw UnsupportedStyleException("style has no sources")
        val bc = sources[SOURCE_ID] as? JsonObject
            ?: throw UnsupportedStyleException("style has no '$SOURCE_ID' source; is it a BombayChitra style?")
        if ((bc["type"] as? JsonPrimitive)?.content != "vector") {
            throw UnsupportedStyleException("'$SOURCE_ID' is not a vector source")
        }
        require(glyphsUri.contains("{fontstack}") && glyphsUri.contains("{range}")) {
            "glyphs URI needs {fontstack} and {range}"
        }
        val newSources = JsonObject(
            sources + (
                SOURCE_ID to buildJsonObject {
                    put("type", "vector")
                    put("url", pmtilesUri)
                    put("attribution", ATTRIBUTION)
                }
                ),
        )
        val rewritten = JsonObject(style + ("sources" to newSources) + ("glyphs" to JsonPrimitive(glyphsUri)))
        return json.encodeToString(JsonObject.serializer(), rewritten)
    }

    /** The style URL of a running BombayChitra server; it needs no rewriting. */
    fun serverStyleUrl(baseUrl: String, theme: MapTheme): String =
        baseUrl.trimEnd('/') + "/styles/" + theme.styleName + ".json"

    /** The URI MapLibre Native uses to read a local PMTiles archive. */
    fun pmtilesFileUri(absolutePath: String): String =
        "pmtiles://file://" + absolutePath.replace('\\', '/').let { if (it.startsWith("/")) it else "/$it" }
}

class UnsupportedStyleException(message: String) : IllegalArgumentException(message)
